            stream['message_count'] += 1
            stream['timestamps'].append(current_time)


            stream['timestamps'] = [t for t in stream['timestamps'] if t >= current_time - 600]


            frequency = stream['message_count'] / (current_time - stream['timestamps'][0])


            stream['time_window'] = int(600 / frequency)

        if self.is_throttled(stream_id):
            print(f"Stream {stream_id} is throttled. Time window: {self.streams[stream_id]['time_window']} seconds")
        else:
            print(f"Stream {stream_id} is not throttled")

    def is_throttled(self, stream_id):
        stream = self.streams[stream_id]
        current_time = tim()  


