    operators = []
    output = []

    # Convert infix to postfix
    for char in expression:
        if char.isdigit() or char == '.':
            output.append(char)
        elif char == '(':
            operators.append(char)
        elif char == ')':
            while operators and operators[-1] != '(':
                output.append(operators.pop())
            operators.pop()
        elif char in '+-*/^':
            while operators and operators[-1] != '(' and precedence[char] <= precedence.get(operators[-1], 0):
                output.append(operators.pop())
            operators.append(char)

    while operators:
        output.append(operators.pop())

    # Evaluate postfix expression
    stack = []
    for char in output:
        if char.isdigit() or char == '.':
            stack.append(float(char))
        elif char in '+-*/^':
            b = stack.pop()
            a = stack.pop()
            if char == '+':
                stack.append(a + b)
            elif char == '-':
                stack.append(a - b)
            elif char == '*':
                stack.append(a * b)
            elif char == '/':
                stack.append(a / b)
            elif char == '^':
                stack.append(a ** b)

    return stack[0]

