        # Initialize distances and visited set
        distances = {start: 0}
        visited = set()

        # Priority queue for nodes to visit
        queue = [(0, start)]

        while queue:
            # Get node with minimum distance from start
            current_distance, current_node = heappop(queue)

            # If the current node is the end, we have found the shortest path
            if current_node == end:
                return distances[current_node]

            # Skip already visited nodes
            if current_node in visited:
                continue

            # Mark current node as visited
            visited.add(current_node)

            # Visit all neighboring nodes
            for neighbor, capacity in self.nodes[current_node].neighbors.items():
                # Skip if neighbor is already visited
                if neighbor in visited:
