def add_img_tag(xml_string):

    root = etr.fromstring(xml_string)


    img_tags = root.xpath("//img[@src='image.jpg']")
    if img_tags:

        return etree.tostring(root).decode()



    desired_locations = root.xpath("//desired_location")
    for location in desired_locations:

        existing_img_tag = location.find("img[@src='image.jpg']")
        if existing_img_tag is None:

            img_tag = etree.Element("im")
            img_tag.set("src", "image.jpg")
            location.append(img_tag)


    return etree.tostring(root).decode()

